import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse('{"title":"Principled Boundaries Between plugin-engine-* and plugin-ext-* Crates","description":"","frontmatter":{"title":"Principled Boundaries Between `plugin-engine-*` and `plugin-ext-*` Crates","type":"adr","date":"2026-09-08T00:00:00.000Z","status":"proposed","status_note":"Proposed."},"headers":[],"relativePath":"handl/project/adrs/0099-plugin-engine-vs-ext-crate-boundaries.md","filePath":"vendored/handl/project/adrs/0099-plugin-engine-vs-ext-crate-boundaries.md"}'),a={name:`handl/project/adrs/0099-plugin-engine-vs-ext-crate-boundaries.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="adr-0099-principled-boundaries-between-plugin-engine-and-plugin-ext-crates" tabindex="-1">ADR-0099: Principled Boundaries Between <code>plugin-engine-*</code> and <code>plugin-ext-*</code> Crates <a class="header-anchor" href="#adr-0099-principled-boundaries-between-plugin-engine-and-plugin-ext-crates" aria-label="Permalink to “ADR-0099: Principled Boundaries Between plugin-engine-* and plugin-ext-* Crates”">​</a></h1><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><p>Establish a strict crate-discipline rule:</p><ol><li><p><code>plugin-engine-&lt;name&gt;</code> crates are <strong>generic, modular, composable engines</strong>.</p><ul><li>They operate on <code>handl_language::Language</code> data and are not tied to the canonical handl v0.1 grammar.</li><li>They contain no canonical rule sets, no embedded <code>handl-kit-data-canonical</code> data, and no <code>hnl</code> subcommand wiring.</li><li>They may expose operation markers, traits, and abstract request/response types (e.g. <code>Typecheck</code>, <code>TypecheckEngine</code>, <code>TypecheckRequest</code>).</li><li>A single engine crate may contain multiple internal modules/algorithms. The typechecker engine, for example, is one crate with modular passes: <code>nbe</code>, <code>refinement</code>, and <code>composite</code>.</li></ul></li><li><p><code>plugin-ext-&lt;name&gt;</code> crates are the <strong>canonical handl bootstrap extension</strong> for a tool.</p><ul><li>They depend on the matching <code>plugin-engine-&lt;name&gt;</code> crate and on <code>handl-kit-data-canonical</code>.</li><li>They supply the canonical rules, language assembly, and the <code>hnl &lt;name&gt;</code> capability wiring.</li><li>They are the only crates that may embed canonical handl rule data or register a <code>hnl</code> subcommand.</li></ul></li><li><p>Existing violations must be remediated:</p><ul><li>Create <code>plugin-ext-typecheck</code> and move the canonical <code>check_module</code> entry point out of <code>plugin-engine-typecheck</code>. <code>plugin-engine-typecheck</code> should retain only the generic <code>Typecheck</code> operation abstraction and the modular engine implementations; <code>plugin-ext-typecheck</code> is the canonical <code>hnl typecheck</code> wrapper.</li><li>Merge <code>plugin-engine-typecheck-nbe</code> into <code>plugin-engine-typecheck</code> as an internal <code>nbe</code> module.</li><li>Convert the arrow-contract inference algorithm from <code>plugin-ext-refinement</code> into a <code>refinement</code> module inside <code>plugin-engine-typecheck</code>. Remove <code>plugin-ext-refinement</code> and the <code>hnlc</code> binary.</li><li>Add a <code>composite</code> (or <code>pipeline</code>) module in <code>plugin-engine-typecheck</code> that runs <code>nbe</code> then <code>refinement</code> on the appropriate fragments.</li></ul></li><li><p>No <code>plugin-ext-*</code> crate may implement a generic algorithm. No <code>plugin-engine-*</code> crate may expose a <code>bin</code> target or a <code>hnl</code> capability.</p></li></ol><h2 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to “Why”">​</a></h2><p>The workspace contains <code>plugin-engine-*</code> and <code>plugin-ext-*</code> crates, but the distinction is not applied consistently. This creates confusion about whether a crate is a generic, data-driven engine or a handl-specific bootstrap tool.</p><h2 id="not-doing" tabindex="-1">Not doing <a class="header-anchor" href="#not-doing" aria-label="Permalink to “Not doing”">​</a></h2><ul><li>none recorded — legacy record; the design doc lists what was deferred.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li>The <code>engine</code>/<code>ext</code> boundary becomes predictable and explainable.</li><li>Generic engines can be reused by future language variants or test <code>Language</code>s without dragging in canonical handl data.</li><li>The <code>hnl</code> CLI wiring is localized to <code>plugin-ext-*</code> crates, consistent with <code>host-cli</code>&#39;s thin-dispatcher design.</li><li>The typechecker becomes one modular, composable crate: <code>nbe</code> and <code>refinement</code> live as modules and can be run independently or composed.</li><li>Refinement becomes a pluggable <code>TypecheckEngine</code> pass, consistent with ADR-0054, instead of a standalone binary.</li></ul><h2 id="enforcement" tabindex="-1">Enforcement <a class="header-anchor" href="#enforcement" aria-label="Permalink to “Enforcement”">​</a></h2><ul><li>Code and tests are named in the design doc.</li></ul><h2 id="design" tabindex="-1">Design <a class="header-anchor" href="#design" aria-label="Permalink to “Design”">​</a></h2><p>The full record (context, tables, phases, trade-offs): <a href="./../design/0099-plugin-engine-vs-ext-crate-boundaries.html"><code>design/0099-plugin-engine-vs-ext-crate-boundaries.md</code></a>.</p>`,14)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};